@startuml

class EBike {
  + frame : Frame
  + driveSystem : DriveSystem
  + controller : Controller
}

class Frame {
  + material : string
}

class DriveSystem {
  + motor : Motor
}

class Motor {}

class Controller {
  + state : ControllerState
}

enum ControllerState {
  On
  Off
  Charging
}

class BasicController extends Controller {}

class AdvancedController extends Controller {
  + nextInspectionDate : date
}

class Battery {
  + storedEnergyWh : float
}

EBike "1" *-- "1" Frame
EBike "1" *-- "1" DriveSystem
EBike "1" *-- "1" Controller
Frame "1" *-- "2" Wheel
EBike "0..1" o-- "1" Battery
Controller "1" --> "0..1" Battery
Controller "1" --> "1" DriveSystem

@enduml

